@startuml

class Employee {
  + name : string
  + ssn : int
}

abstract class CreativeEmployee {
  + hasOscar : boolean
}

class Director {
  + assistantName : string
}

class Actor {
  + education : string
}

class Technician {
  + fieldOfActivity : string
}

class FilmSet {
  + location : string
}

class Film {
  + title : string
  + releaseYear : int
}

enum Genre {
  Thriller
  Action
  Horror
  Comedy
}

class Screenwriter {
  + name : string
  + mostSuccessfulFilm : string
}

class Screenplay {
  + title : string
  + version : string
  + date : date
  + numberOfScenes : int
  + plot : string
}

class Novel {
  + title : string
  + author : string
}

class Concept {}

Director --|> CreativeEmployee
Actor --|> CreativeEmployee
Technician --|> Employee
CreativeEmployee --|> Employee

FilmSet "*" -- "*" Film
Film "*" -- "1" Genre

Screenwriter "1" -- "*" Screenplay : creates
Screenplay "*" -- "1" Screenwriter : comes from

Screenplay --|> Novel
Screenplay --|> Concept

Film "1" -- "1" Screenplay : based on
Film "1" -- "1..*" FilmSet : shot at

Actor "1..*" -- "1" Screenplay : reads
Director "1" -- "1" Screenplay : implements

